   422→// preTaskFilePrefix is the prefix for pre-task state files
   423→const preTaskFilePrefix = "pre-task-"
   424→
   425→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   426→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   427→// When multiple pre-task files exist (nested subagents), returns the most recently
   428→// modified one.
   429→// Works correctly from any subdirectory within the repository.
   430→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
   431→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   432→	if err != nil {
   433→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   434→	}
   435→	entries, err := os.ReadDir(tmpDirAbs)
   436→	if err != nil {
   437→		return "", false
   438→	}
   439→
   440→	var latestFile string
   441→	var latestTime time.Time
   442→
   443→	for _, entry := range entries {
   444→		if entry.IsDir() {
   445→			continue
   446→		}
   447→		name := entry.Name()
   448→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   449→			continue
   450→		}
   451→
   452→		// Check modification time for nested subagent handling
   453→		info, err := entry.Info()
   454→		if err != nil {
   455→			continue
   456→		}
   457→		if latestFile == "" || info.ModTime().After(latestTime) {
   458→			latestFile = name
   459→			latestTime = info.ModTime()
   460→		}
   461→	}
   462→
   463→	if latestFile == "" {
   464→		return "", false
   465→	}
   466→
   467→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   468→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   469→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   470→	return toolUseID, true
   471→}
