   473→// DetectChangedFiles detects files that have been modified, added, or deleted
   474→// since the last commit (or compared to the index for incremental checkpoints).
   475→// Returns three slices: modified files, new (untracked) files, and deleted files.
   476→// Excludes .entire/ directory from all results.
   477→func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
   478→	repo, err := openRepository()
   479→	if err != nil {
   480→		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
   481→	}
   482→
   483→	worktree, err := repo.Worktree()
   484→	if err != nil {
   485→		return nil, nil, nil, fmt.Errorf("failed to get worktree: %w", err)
   486→	}
   487→
   488→	status, err := worktree.Status()
   489→	if err != nil {
   490→		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
   491→	}
   492→
   493→	for file, st := range status {
   494→		// Skip .entire directory
   495→		if paths.IsInfrastructurePath(file) {
   496→			continue
   497→		}
   498→
   499→		// Handle different status codes
   500→		// Worktree status indicates changes not yet staged
   501→		// Staging status indicates changes staged for commit
   502→		switch {
   503→		case st.Worktree == git.Untracked:
   504→			// New untracked file
   505→			newFiles = append(newFiles, file)
   506→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
   507→			// Deleted file
   508→			deleted = append(deleted, file)
   509→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
   510→			st.Worktree == git.Added || st.Staging == git.Added:
   511→			// Modified or staged file
   512→			modified = append(modified, file)
   513→		}
   514→	}
   515→
   516→	return modified, newFiles, deleted, nil
   517→}
