   519→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   520→// It counts existing checkpoint files in the task metadata checkpoints directory.
   521→// Returns 1 if no checkpoints exist yet.
   522→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   523→	// ctx.SessionID is already an Entire session ID (date-prefixed), so use SessionMetadataDirFromEntireID
   524→	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   525→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
