   916→// InitializeSession creates session state for a new session.
   917→// This is called during UserPromptSubmit hook to set up tracking for the session.
   918→// For auto-commit strategy, this creates a SessionState file in .git/entire-sessions/
   919→// to track CondensedTranscriptLines (transcript offset) across checkpoints.
   920→// agentType is the human-readable name of the agent (e.g., "Claude Code").
   921→// transcriptPath is the path to the live transcript file (for mid-session commit detection).
   922→func (s *AutoCommitStrategy) InitializeSession(sessionID string, agentType agent.AgentType, transcriptPath string) error {
   923→	repo, err := OpenRepository()
   924→	if err != nil {
   925→		return fmt.Errorf("failed to open git repository: %w", err)
   926→	}
   927→
   928→	// Get current HEAD commit to track as base
   929→	head, err := repo.Head()
   930→	if err != nil {
   931→		return fmt.Errorf("failed to get HEAD: %w", err)
   932→	}
   933→
   934→	baseCommit := head.Hash().String()
   935→
   936→	// Check if session state already exists (e.g., session resuming)
   937→	existing, err := LoadSessionState(sessionID)
   938→	if err != nil {
   939→		return fmt.Errorf("failed to check existing session state: %w", err)
   940→	}
   941→	if existing != nil {
   942→		// Session already initialized, nothing to do
   943→		return nil
   944→	}
   945→
   946→	// Create new session state
   947→	state := &SessionState{
   948→		SessionID:                sessionID,
   949→		BaseCommit:               baseCommit,
   950→		StartedAt:                time.Now(),
   951→		CheckpointCount:          0,
   952→		CondensedTranscriptLines: 0, // Start from beginning of transcript
   953→		FilesTouched:             []string{},
   954→		AgentType:                agentType,
   955→		TranscriptPath:           transcriptPath,
   956→	}
   957→
   958→	if err := SaveSessionState(state); err != nil {
   959→		return fmt.Errorf("failed to save session state: %w", err)
   960→	}
   961→
   962→	return nil
   963→}
