   246→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   247→// infrastructure paths and paths outside the repo.
   248→func FilterAndNormalizePaths(files []string, cwd string) []string {
   249→	var result []string
   250→	for _, file := range files {
   251→		relPath := paths.ToRelativePath(file, cwd)
   252→		if relPath == "" {
   253→			continue // outside repo
   254→		}
   255→		if paths.IsInfrastructurePath(relPath) {
   256→			continue // skip .entire directory
   257→		}
   258→		result = append(result, relPath)
   259→	}
   260→	return result
   261→}
