   273→// getUntrackedFilesForState returns a list of untracked files using go-git
   274→// Excludes .entire directory
   275→func getUntrackedFilesForState() ([]string, error) {
   276→	repo, err := openRepository()
   277→	if err != nil {
   278→		return nil, err
   279→	}
   280→
   281→	worktree, err := repo.Worktree()
   282→	if err != nil {
   283→		return nil, err
   284→	}
   285→
   286→	status, err := worktree.Status()
   287→	if err != nil {
   288→		return nil, err
   289→	}
   290→
   291→	var untrackedFiles []string
   292→	for file, st := range status {
   293→		if st.Worktree == git.Untracked {
   294→			// Exclude .entire directory
   295→			if !strings.HasPrefix(file, paths.EntireDir+"/") && file != paths.EntireDir {
   296→				untrackedFiles = append(untrackedFiles, file)
   297→			}
   298→		}
   299→	}
   300→
   301→	return untrackedFiles, nil
