   524→	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   525→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   526→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   527→
   528→	entries, err := os.ReadDir(checkpointsDir)
   529→	if err != nil {
   530→		// Directory doesn't exist or can't be read - start at 1
   531→		return 1
   532→	}
   533→
   534→	// Count JSON files (checkpoints)
   535→	count := 0
   536→	for _, entry := range entries {
   537→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   538→			count++
   539→		}
   540→	}
   541→
   542→	return count + 1
   543→}
